<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,watch,nextTick} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import {Save,Plus,Trash2,Eye,BookOpen,Upload,Send} from 'lucide-vue-next'
import {api,newKey,ApiError} from '../api'
import {useApp} from '../stores/app'
import {useRequestScope} from '../platform/request-scope'
import PageHeader from '../workspace/PageHeader.vue'
import AuthorFieldDesigner from './AuthorFieldDesigner.vue'
import AuthorTrialPanel from './AuthorTrialPanel.vue'
import AuthorInitialSettings from './AuthorInitialSettings.vue'
import AuthorPlotEditor from './AuthorPlotEditor.vue'
import AuthorStartFields from './AuthorStartFields.vue'
import StateFields from './StateFields.vue'
import {cacheGet,cacheSet} from '../platform/bridge'
import {draftDiff} from './draft-diff'
import {authorCost} from './cost'
import Sheet from '../components/Sheet.vue'
import WorldLookLibrary from '../components/WorldLookLibrary.vue'
import type {AuthorDraft,PublicationStatus} from './types'
import './authoring.css'
const route=useRoute(),router=useRouter(),worldId=String(route.params.worldId),store=useApp(),capture=useRequestScope(()=>worldId,()=>route.path),draft=ref<AuthorDraft>(),tab=ref('basic'),busy=ref(false),error=ref(''),notice=ref(''),preview=ref(false),rights=ref(false),attribution=ref(''),loaded=ref(''),raw=ref(''),editingRaw=ref(false)
const value=computed(()=>draft.value?.value),dirty=computed(()=>!!draft.value&&JSON.stringify(draft.value.value)!==loaded.value),characters=computed(()=>value.value?.definition.entities.filter(e=>e.type==='character')||[]),places=computed(()=>value.value?.definition.entities.filter(e=>e.type==='place')||[])
const costParts=computed(()=>value.value?authorCost(value.value):[])
const tabs=[['basic','作品介绍'],['world','世界与人物'],['knowledge','知识设定'],['openings','多开局'],['fields','表单与状态栏'],['plot','任务与结局'],['publish','发布管理'],['test','保存与试玩']]
function selectedTab(value:unknown){return typeof value==='string'&&tabs.some(([id])=>id===value)?value:'basic'}
tab.value=selectedTab(route.query.tab)
watch(()=>route.query.tab,value=>{tab.value=selectedTab(value)})
function selectTab(value:string){tab.value=value;void router.push({path:route.path,query:{...route.query,tab:value}})}
const labels:Record<string,string>={pending:'审核中',published:'已发布',rejected:'未通过审核',withdrawn:'已撤下',removed:'管理员已下架'}
let saveIntent:{body:string;key:string}|undefined,submitIntent:{body:string;key:string}|undefined
const localDraft=ref<{worldId:string;baseVersion:number;value:AuthorDraft['value'];savedAt:string}>(),remoteDraft=ref<AuthorDraft>(),comparing=ref(false),draftStatus=ref(''),find=ref(''),previewValues=ref<Record<string,string|number|boolean|string[]|null>>({}),previewOpening=ref('')
const draftSlot='world-author-draft:'+worldId,differences=computed(()=>draftDiff(value.value,remoteDraft.value?.value)),localDifferences=computed(()=>draftDiff(localDraft.value?.value,value.value))
let draftTimer:ReturnType<typeof setTimeout>|undefined
async function cacheDraft(){if(!draft.value||!dirty.value)return;const scope=capture();try{await cacheSet(draftSlot,{worldId,baseVersion:draft.value.version,value:JSON.parse(JSON.stringify(draft.value.value)),savedAt:new Date().toISOString()});if(scope.valid())draftStatus.value='未保存的修改已暂存到此设备'}catch{if(scope.valid())draftStatus.value='此设备暂存失败，请立即保存作者配置'}}
watch(value,()=>{clearTimeout(draftTimer);if(dirty.value)draftTimer=setTimeout(()=>void cacheDraft(),250)},{deep:true})
async function restoreDraft(){if(localDraft.value&&draft.value){draft.value.value=localDraft.value.value;localDraft.value=undefined;notice.value='已恢复本机草稿，请检查并保存。';await cacheDraft()}}
async function discardDraft(){await cacheSet(draftSlot,null);localDraft.value=undefined}
async function compareLatest(){const scope=capture();try{const result=await api<AuthorDraft>('/authoring/worlds/'+worldId);if(scope.valid()){remoteDraft.value=result;comparing.value=true}}catch(e){if(scope.valid())error.value=(e as Error).message}}
function keepLocal(){if(!draft.value||!remoteDraft.value)return;draft.value.version=remoteDraft.value.version;loaded.value=JSON.stringify(remoteDraft.value.value);comparing.value=false;notice.value='已确认差异，保留本机编辑；保存时仍会检查服务器版本。';void cacheDraft()}
function useRemote(){if(!remoteDraft.value)return;draft.value=remoteDraft.value;loaded.value=JSON.stringify(draft.value.value);comparing.value=false;void discardDraft()}
function addFixed(){(value.value!.fixedActions??=[]).push({id:'action-'+crypto.randomUUID().slice(0,8),label:'新的行动',message:'观察周围，先不改变任何物品。',kind:'observe'})}
const leaving=ref(false);let leaveDecision:((allow:boolean)=>void)|undefined
function decideLeave(allow:boolean){leaving.value=false;leaveDecision?.(allow);leaveDecision=undefined}
function protectChanges(to:{path:string}){if(to.path===route.path||!dirty.value||!store.user||['/login','/register','/recover'].includes(to.path))return true;return new Promise<boolean>(resolve=>{leaveDecision?.(false);leaveDecision=resolve;leaving.value=true})}
onBeforeRouteLeave(async to=>{await cacheDraft();return protectChanges(to)});onBeforeRouteUpdate(protectChanges)
async function saveAndLeave(){await save();if(!dirty.value&&!error.value)decideLeave(true)}
function beforeUnload(event:BeforeUnloadEvent){if(dirty.value){void cacheDraft();event.preventDefault();event.returnValue=''}}
onMounted(()=>window.addEventListener('beforeunload',beforeUnload));onUnmounted(()=>{window.removeEventListener('beforeunload',beforeUnload);leaveDecision?.(false);clearTimeout(draftTimer)})
function intent(body:unknown,kind:'save'|'submit'){const serialized=JSON.stringify(body),old=kind==='save'?saveIntent:submitIntent;const current=old?.body===serialized?old:{body:serialized,key:newKey()};if(kind==='save')saveIntent=current;else submitIntent=current;return current.key}
async function load(){const scope=capture();busy.value=true;error.value='';try{const result=await api<AuthorDraft>('/authoring/worlds/'+worldId);if(scope.valid()){draft.value=result;loaded.value=JSON.stringify(result.value);editingRaw.value=false;const cached=await cacheGet<typeof localDraft.value>(draftSlot);if(scope.valid()&&cached&&JSON.stringify(cached.value)!==loaded.value)localDraft.value=cached}}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false}}
async function save(){if(!draft.value||busy.value||editingRaw.value)return;const scope=capture(),body={expectedVersion:draft.value.version,value:structuredClone(JSON.parse(JSON.stringify(value.value)))};busy.value=true;error.value='';notice.value='';try{const result=await api<AuthorDraft>('/authoring/worlds/'+worldId,{method:'PUT',body,key:intent(body,'save')});if(scope.valid()){draft.value=result;loaded.value=JSON.stringify(result.value);notice.value='配置已保存，新开局会使用这一版；已有世界线保持原设定。';saveIntent=undefined;draftStatus.value='';await discardDraft()}}catch(e){if(scope.valid()){error.value=(e as Error).message;if(e instanceof ApiError&&e.status===409)void compareLatest()}}finally{if(scope.valid())busy.value=false}}
function addOpening(){value.value?.openings.push({id:'opening-'+Date.now(),title:'新的开局',description:'',text:'观察眼前的处境。',characterId:characters.value[0]?.id||null,locationId:places.value[0]?.id||null})}
function moveItem<T>(items:T[],index:number,direction:number){const target=index+direction;if(target<0||target>=items.length)return;[items[index],items[target]]=[items[target],items[index]]}
function editDefinition(){raw.value=JSON.stringify(value.value?.definition,null,2);editingRaw.value=true}
function applyDefinition(){try{const next=JSON.parse(raw.value);if(!Array.isArray(next.entities)||!Array.isArray(next.lore)||!next.initial)throw Error();if(value.value)value.value.definition=next;editingRaw.value=false;error.value=''}catch{error.value='设定 JSON 无法读取，请检查实体、初始状态和知识条目。'}}
function addEntity(){value.value?.definition.entities.push({id:'character-'+Date.now(),name:'新人物',type:'character',description:'',traits:'',hiddenGoal:'',source:'user',knownBy:[],knownFacts:[],aliases:[],evidence:[]})}
function addLore(){value.value?.definition.lore.push({id:'lore-'+Date.now(),title:'新的设定',text:'补充这一条世界设定。',triggers:[],knownBy:[],entityIds:[],source:'user',evidence:[]})}
async function cover(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file||!value.value)return;error.value='';try{if(file.size>550000||!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('请选择小于 550 KB 的 PNG、JPEG 或 WebP 封面。');const data=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=reject;reader.readAsDataURL(file)});if(value.value)value.value.coverDataUrl=data}catch(e){error.value=(e as Error).message}}
async function submit(){if(!draft.value||dirty.value||busy.value)return;const scope=capture(),body={expectedVersion:draft.value.publication?.version||0,authorVersion:draft.value.version,rightsConfirmed:rights.value,attribution:attribution.value};busy.value=true;error.value='';try{const result=await api<PublicationStatus>('/authoring/worlds/'+worldId+'/submit',{method:'POST',body,key:intent(body,'submit')});if(scope.valid()&&draft.value){draft.value.publication=result;notice.value='已提交审核。通过后，其他账号才能发现和游玩这一版作品。';submitIntent=undefined}}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false}}
async function withdraw(){const publication=draft.value?.publication;if(!publication||busy.value)return;const scope=capture();busy.value=true;error.value='';try{const result=await api<PublicationStatus>('/authoring/publications/'+publication.id+'/withdraw',{method:'POST',body:{expectedVersion:publication.version},key:newKey()});if(scope.valid()&&draft.value){draft.value.publication=result;notice.value='作品已撤下。读者已经保存的私人世界线仍可继续。'}}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false}}
const trialPanel=ref<InstanceType<typeof AuthorTrialPanel>>()
async function saveAndTry(){if(dirty.value||!draft.value?.version)await save();await nextTick();if(!dirty.value&&!error.value)await trialPanel.value?.start()}
function openTrial(){preview.value=false;selectTab('test')}
onMounted(load)
</script>
<template><div class="workspace-page author-page"><PageHeader title="作者工作台" eyebrow="创作与发布" description="配置新开局，先预览和试玩，再提交公开。"><button :disabled="!value||busy" @click="openTrial">保存后试玩</button><button :disabled="!value||busy" @click="preview=true"><Eye :size="17"/>预览</button><button class="primary" :disabled="!value||busy||!store.online||editingRaw" @click="save"><Save :size="17"/>{{busy?'正在处理…':'保存作者配置'}}</button></PageHeader>
<details v-if="value&&tab!=='test'" class="author-cost-hint workspace-card"><summary>当前设定量与试玩预算</summary><p>随编辑实时估算。此处按首个开局统计；选定其他开局后的估算和可用通道预算请进入保存后试玩。</p><dl><template v-for="part in costParts" :key="part.id"><dt>{{part.title}}</dt><dd>{{part.characters.toLocaleString()}} 字符 · 约 {{part.low.toLocaleString()}}–{{part.high.toLocaleString()}} tokens</dd></template></dl><p>人物与知识按场景和触发条件选入，不是全部常驻。金额未知；设定量不含实际历史、系统指令与图像开销，任务回执另列真实用量。</p><button @click="openTrial">查看模型与测试预算</button></details>
<p v-if="error" role="alert" class="error">{{error}} <button :disabled="busy" @click="compareLatest">比较服务器版本</button></p><p v-if="draftStatus" role="status">{{draftStatus}}</p><section v-if="localDraft" class="workspace-card" aria-label="找回未保存草稿"><h2>发现上次未保存的草稿</h2><p>{{new Date(localDraft.savedAt).toLocaleString()}} · 草稿基于版本 {{localDraft.baseVersion}}，服务器为 {{draft?.version}}。请先核对差异。</p><details><summary>查看草稿与服务器差异</summary><article v-for="row in localDifferences" :key="row.path"><strong>{{row.path}}</strong><p>本机：{{row.local}}</p><p>服务器：{{row.remote}}</p></article></details><button @click="restoreDraft">恢复草稿继续编辑</button><button @click="discardDraft">放弃这份草稿</button></section><p v-if="notice" role="status" class="product-hint">{{notice}}</p><p v-if="!draft&&!error" role="status">正在读取作者配置…</p>
<template v-if="draft&&value"><div class="author-version">配置版本 {{draft.version}} <span v-if="dirty">· 有未保存修改</span><span v-if="draft.hasSaves">· 修改仅用于新开局</span></div><label v-if="tab==='world'||tab==='knowledge'">查找人物或知识<input v-model="find" type="search" placeholder="名称、描述或设定内容"></label><nav class="workspace-pills author-tabs" aria-label="作者配置分类"><button v-for="[id,label] in tabs" :key="id" :aria-pressed="tab===id" @click="selectTab(id)">{{label}}</button></nav>
<Sheet v-if="leaving" title="未保存的作者配置" @close="decideLeave(false)"><p>这些修改尚未保存，是否保存后离开？</p><div class="public-actions"><button class="primary" :disabled="busy||editingRaw" @click="saveAndLeave">保存后离开</button><button :disabled="busy" @click="decideLeave(true)">放弃修改并离开</button><button :disabled="busy" @click="decideLeave(false)">继续编辑</button></div></Sheet><fieldset :disabled="busy" class="author-form">
<section v-if="tab==='basic'" class="workspace-card"><h2>作品介绍</h2><label>作品名称<input aria-label="作品名称" v-model="value.title" maxlength="160"></label><label>作品摘要<textarea aria-label="作品摘要" v-model="value.summary" maxlength="500" rows="3"></textarea></label><label>详细介绍<textarea aria-label="详细介绍" v-model="value.introduction" maxlength="4000" rows="6"></textarea></label><div class="author-columns"><label>作品分类<select aria-label="作品分类" v-model="value.genre"><option value="general">综合故事</option><option value="mystery">悬疑调查</option><option value="romance">人物情感</option><option value="fantasy">奇幻冒险</option><option value="political">势力权谋</option><option value="survival">生存探索</option></select></label><label>作品标签（逗号分隔）<input aria-label="作品标签（逗号分隔）" :value="value.tags.join('，')" @change="value.tags=($event.target as HTMLInputElement).value.split(/[,，]/).map(s=>s.trim()).filter(Boolean)"></label></div><h3>作品封面</h3><div class="author-cover" :data-theme="value.coverTheme"><img v-if="value.coverDataUrl" :src="value.coverDataUrl" alt="作品封面预览"><BookOpen v-else :size="46"/><strong>{{value.title}}</strong></div><label>封面配色<select aria-label="封面配色" v-model="value.coverTheme"><option value="paper">纸色</option><option value="blue">雾蓝</option><option value="forest">森林</option><option value="rose">暮色</option></select></label><label><Upload :size="17"/>上传封面<input type="file" accept="image/png,image/jpeg,image/webp" @change="cover"></label><button v-if="value.coverDataUrl" type="button" @click="value.coverDataUrl=''">移除封面图片</button></section>
<section v-if="tab==='world'" class="workspace-card"><h2>世界规则</h2><label>叙事与导演说明<textarea aria-label="叙事与导演说明" v-model="value.authorInstructions" maxlength="4000" rows="5"></textarea><small>用于叙事风格和人物行为，不能替代实际状态、物品交接或结局验收。</small></label><div class="author-columns"><label>写作风格<input aria-label="写作风格" v-model="value.rules.style" maxlength="500"></label><label>开场时间<input aria-label="开场时间" v-model="value.definition.timeLabel" maxlength="100"></label></div><label>补充规则<textarea aria-label="补充规则" v-model="value.rules.customRules" maxlength="1500" rows="3"></textarea></label><div class="author-columns"><label>死亡规则<select aria-label="死亡规则" v-model="value.rules.deathPolicy"><option value="end">死亡后结束</option><option value="rescue">等待救援</option><option value="rebirth">有代价的重生</option></select></label><label>叙事节奏<select aria-label="叙事节奏" v-model="value.rules.pace"><option value="short">简短</option><option value="standard">标准</option><option value="detailed">细腻</option></select></label></div><h2>人物与实体</h2><WorldLookLibrary :world-id="worldId" :disabled="busy||dirty"/><p class="muted">先保存角色设定，再生成或上传头像与立绘。采用的形象会随公开版本发布，读者可以在自己的副本中更换。</p><article v-for="entity in value.definition.entities" :key="entity.id" class="author-item" v-show="!find||(entity.name+entity.description).includes(find)"><div class="row between"><h3>{{entity.name}}</h3><button :aria-label="'删除实体 '+entity.name" @click="value.definition.entities=value.definition.entities.filter(e=>e.id!==entity.id)"><Trash2 :size="16"/></button></div><div class="author-columns"><label>实体名称<input aria-label="实体名称" v-model="entity.name" maxlength="100"></label><label>实体类型<select aria-label="实体类型" v-model="entity.type"><option value="character">人物</option><option value="place">地点</option><option value="item">物品</option><option value="faction">势力</option></select></label></div><label>实体描述<textarea aria-label="实体描述" v-model="entity.description" maxlength="1000" rows="2"></textarea></label><label v-if="entity.type==='character'">性格与说话方式<input v-model="entity.traits" maxlength="500"></label><label v-if="entity.type==='character'">隐藏动机<input v-model="entity.hiddenGoal" maxlength="400"><small>仅导演使用，作品公开介绍不会显示。</small></label><small class="muted">标识：{{entity.id}}</small></article><button :disabled="value.definition.entities.length>=50" @click="addEntity"><Plus :size="16"/>添加人物或实体</button><AuthorInitialSettings :value="value"/><details><summary>完整设定 JSON（高级）</summary><p>高级编辑可配置路线、初始物品、实体可见性和关联。保存时会检查引用，已有蓝宝石任务与善后条件继续保留。</p><button v-if="!editingRaw" @click="editDefinition">编辑完整世界设定</button><template v-else><label>世界设定 JSON<textarea aria-label="世界设定 JSON" v-model="raw" rows="18" spellcheck="false"></textarea></label><button @click="applyDefinition">应用世界设定</button><button @click="editingRaw=false">取消高级编辑</button></template></details></section>
<section v-if="tab==='knowledge'" class="workspace-card"><h2>知识设定</h2><p>知识按触发词检索，并遵守人物的已知范围。未公开的真相不会放进作品介绍。</p><article v-for="lore in value.definition.lore" :key="lore.id" v-show="!find||[lore.title,lore.text,...lore.triggers].join(' ').toLowerCase().includes(find.toLowerCase())" class="author-item"><label>条目名称<input aria-label="条目名称" v-model="lore.title" maxlength="150"></label><label>设定内容<textarea aria-label="设定内容" v-model="lore.text" maxlength="1200" rows="4"></textarea></label><label>触发词（逗号分隔）<input aria-label="触发词（逗号分隔）" :value="lore.triggers.join('，')" @change="lore.triggers=($event.target as HTMLInputElement).value.split(/[,，]/).map(s=>s.trim()).filter(Boolean)"></label><label>知晓范围<select aria-label="知晓范围" multiple v-model="lore.knownBy"><option value="all">所有人已知</option><option value="player">玩家已知</option><option v-for="c in characters" :key="c.id" :value="c.id">{{c.name}}</option></select><small>不选择表示仅在导演推演中使用。</small></label><button @click="value.definition.lore=value.definition.lore.filter(l=>l.id!==lore.id)">删除条目</button></article><button :disabled="value.definition.lore.length>=50" @click="addLore"><Plus :size="16"/>添加知识条目</button></section>
<section v-if="tab==='openings'" class="workspace-card"><h2>多开局</h2><label>建议文本模型<input v-model="value.suggestedModel" maxlength="120" placeholder="模型标识，如 mimo-v2.6-flash；留空跟随玩家默认"></label><p>只有玩家账号有权使用的文本通道才能生效，作品不会携带作者密钥。</p><h3>固定行动按钮</h3><article v-for="(action,i) in value.fixedActions" :key="action.id" class="author-item"><label>按钮名称<input v-model="action.label" maxlength="40"></label><label>行动内容<textarea v-model="action.message" maxlength="1000"></textarea></label><label>行动方式<select v-model="action.kind"><option value="action">行动</option><option value="dialogue">对话</option><option value="observe">观察</option><option value="wait">等待</option></select></label><button @click="value.fixedActions!.splice(i,1)">删除行动按钮</button></article><button :disabled="(value.fixedActions?.length||0)>=12" @click="addFixed">添加固定行动</button><p>每个开局可以指定身份、地点和第一轮行动。修改只影响以后新建的世界线。</p><article v-for="(opening,i) in value.openings" :key="opening.id" class="author-item"><div class="row between"><h3>开局 {{i+1}}</h3><div class="row"><button :disabled="i===0" :aria-label="'上移开局 '+opening.title" @click="moveItem(value.openings,i,-1)">上移</button><button :disabled="i===value.openings.length-1" :aria-label="'下移开局 '+opening.title" @click="moveItem(value.openings,i,1)">下移</button></div><button :disabled="value.openings.length===1" :aria-label="'删除开局 '+opening.title" @click="value.openings.splice(i,1)"><Trash2 :size="16"/></button></div><label>开局名称<input aria-label="开局名称" v-model="opening.title" maxlength="80"></label><label>开局简介<textarea aria-label="开局简介" v-model="opening.description" maxlength="400" rows="2"></textarea></label><label>开场行动<textarea aria-label="开场行动" v-model="opening.text" maxlength="1200" rows="4"></textarea></label><div class="author-columns"><label>推荐身份<select aria-label="推荐身份" v-model="opening.characterId"><option :value="null">由玩家选择</option><option v-for="c in characters" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>起始地点<select aria-label="起始地点" v-model="opening.locationId"><option :value="null">使用人物原地点</option><option v-for="place in places" :key="place.id" :value="place.id">{{place.name}}</option></select></label></div></article><button :disabled="value.openings.length>=10" @click="addOpening"><Plus :size="16"/>添加开局</button></section>
<section v-if="tab==='fields'" class="workspace-card"><AuthorFieldDesigner :value="value"/></section>
<section v-if="tab==='plot'" class="workspace-card"><AuthorPlotEditor :value="value"/></section><section v-if="tab==='publish'" class="workspace-card"><h2>发布管理</h2><p>公开版本包含可游玩的世界设定、开局及知识。私人原文件、聊天、个人模型密钥和已有玩家存档不会随作品公开。</p><p>公开后，其他账号可以保存独立副本并编辑其中的玩法设定；撤下作品不会删除已经保存的副本。</p><p v-if="draft.publication" role="status">状态：{{labels[draft.publication.state]||draft.publication.state}} · {{draft.publication.live?'当前已有公开版本':'当前没有公开版本'}}</p><blockquote v-if="draft.publication?.note">审核说明：{{draft.publication.note}}</blockquote><p v-if="draft.publication?.live&&draft.publication.state==='pending'">新版审核期间，读者继续看到上次通过审核的版本。</p><p v-if="dirty" class="product-hint">请先保存修改，再提交审核。</p><label>作品来源与授权说明<textarea aria-label="作品来源与授权说明" v-model="attribution" maxlength="500" rows="3" placeholder="例如：原创作品；或公版原作、作者及改编说明"></textarea></label><label class="author-check"><input v-model="rights" type="checkbox">我确认可以公开本作品的文字、设定及封面</label><div class="product-actions"><button class="primary" :disabled="busy||dirty||!draft.version||!rights||!attribution.trim()||!store.online" @click="submit"><Send :size="17"/>提交当前版本审核</button><button v-if="draft.publication&&(draft.publication.live||draft.publication.state==='pending')" :disabled="busy||!store.online" @click="withdraw">撤下作品与申请</button><RouterLink v-if="draft.publication?.live" :to="'/published/'+draft.publication.id" class="inline-link">查看公开作品页</RouterLink><button @click="openTrial">先用独立测试世界试玩</button></div></section>
</fieldset><AuthorTrialPanel v-if="tab==='test'" ref="trialPanel" :world-id="worldId" :value="value" :version="draft.version" :dirty="dirty" :busy="busy" @start="saveAndTry" @edit="selectTab"/><Sheet v-if="comparing&&remoteDraft" title="对比服务器版本" @close="comparing=false"><p>服务器版本 {{remoteDraft.version}}。当前编辑尚未被覆盖。</p><p v-if="!differences.length">内容一致。</p><article v-for="row in differences" :key="row.path"><strong>{{row.path}}</strong><p>本机：{{row.local}}</p><p>服务器：{{row.remote}}</p></article><button @click="keepLocal">已核对，保留本机编辑</button><button @click="useRemote">使用服务器版本</button><button @click="comparing=false">继续检查</button></Sheet><Sheet v-if="preview" title="作品与开局预览" @close="preview=false"><h2>{{value.title}}</h2><p>{{value.summary}}</p><p class="author-prose">{{value.introduction}}</p><article v-for="opening in value.openings" :key="opening.id" class="author-item"><h3>{{opening.title}}</h3><p>{{opening.description}}</p><p class="author-prose">{{opening.text}}</p><small>{{characters.find(c=>c.id===opening.characterId)?.name||'玩家选择身份'}} · {{places.find(p=>p.id===opening.locationId)?.name||'人物原地点'}}</small></article><h3>实际开局组件</h3><AuthorStartFields :config="value" v-model:opening-id="previewOpening" v-model:values="previewValues"/><h3>实际状态显示</h3><StateFields :fields="value.statusFields" :values="Object.fromEntries(value.statusFields.map(f=>[f.id,f.defaultValue]))"/><p>预览不调用模型。实际试玩请先保存配置。</p><button @click="openTrial">保存后进入独立试玩</button></Sheet></template></div></template>
